$q=$pdo->prepare('SELECT COUNT(*) FROM legado_2026_profile_changes a WHERE '.$where);$q->execute($params);$total=(int)$q->fetchColumn();$pages=max(1,(int)ceil($total/$size));$page=min($page,$pages);$offset=($page-1)*$size;
